INSERT INTO catalog.course (public_id, title, concept, description, image, level, duration, instructor, cost, point_price, reward, language_id, category_id, access_model, publish_status, is_hidden, is_deleted)
VALUES ('ai-llm-foundations', 'AI & LLM Foundations for Developers: Tokens, Cost, Hallucinations & Choosing a Model', 'Understand how a large language model produces text at the level an engineer needs: tokens and probabilities, the context window, temperature, cost and latency, why models answer confidently and wrongly, how to choose a model for a task and its data, and what you must tell users when a product uses AI.', 'A beginner course for developers who use ChatGPT, Gemini, Claude or DeepSeek every day and now have to build with them. Every lesson starts from a situation on the CodeDev learning platform - a hint bot that invented a parameter of an API that changed last year, a monthly bill ten times the estimate, an answer that changes every time a learner asks again, a support prompt that pasted a learner''s email into a third-party API - and explains it with numbers you can check: tokens and context windows, temperature and repeatability, cost and latency per request, hallucination versus missing context, knowledge cutoff, choosing between a large and a small model or one that runs locally, data privacy and transparency duties under Vietnam''s AI Law. No real model is called in the challenges: they run on recorded fixtures. 10 lessons with True/False quizzes on real prompts and logs, and TypeScript challenges graded by hidden tests.', 'https://res.cloudinary.com/dex6q1cqh/image/upload/c_limit,w_1600/f_auto,q_auto/v1793018087/codedev/courses/ai-llm-foundations/cover', 'beginner'::level_enum, 220, 'CodeDev Engineering Team', 0, 0, 50,
