WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_121'), 'The tutor sent a 31-message chat with max_completion_tokens: 1000 and got:

400 {"error":{"code":"context_length_exceeded","message":"This model''s maximum context length is 8192 tokens. However, you requested 8650 tokens (7650 in the messages, 1000 in the completion)."}}

Statement: "Sending the same 31 messages with max_completion_tokens: 500 would make this request fit the context window."', 'single_choice'::question_type, 'True. The context window is one budget for input and output together: 7650 tokens of messages plus 500 requested for the answer is 8150, which is within 8192. That shows how the window is counted, but it is only a stopgap: the answer now has half the room, and the next turn adds more messages, so the chat fails again a turn or two later. The lasting fix is to trim the history to a budget of window minus reserved output. The misconception is that the context window limits only what you send, so the output limit could not matter.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_121') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
