WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_121'), 'A second proposed fix for the tutor:

const messages = [{ role: "system", content: TUTOR_RULES }, ...chat];
while (countTokens(messages) > 7000) {
  messages.shift();          // drop the oldest message
}
const response = await client.chat.completions.create({ model, max_completion_tokens: 1000, messages });

Statement: "Because the system prompt is added before the chat, this loop removes only old chat turns and the tutor rules are always sent."', 'single_choice'::question_type, 'False. The system prompt is the first element of the array, and shift() removes the first element, so it is the very first thing this loop drops when the chat is too long. From then on every request reaches the model without the rules, and the model has no memory of them from earlier requests. Keep the system prompt outside the part you trim (or always put it back first) and trim only the history, oldest first. The misconception is that being first in the array makes a message safe; with front-trimming it makes it the first to go.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_121') AND order_index = 2)
    RETURNING id
)
