-- challenge chal_coding_aif_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aif_122', (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aif-1-2' AND is_deleted = false LIMIT 1), 'fit-chat-into-context', 'Trim a chat to fit the context window', 'CodeDev''s AI tutor resends the whole chat on every turn. Long chats failed with context_length_exceeded, and a hotfix that kept the last 20 entries cut the system prompt, so the tutor stopped following its rules. Write fitContext(req). The budget for the input is req.contextLimit - req.reservedOutputTokens. Always send the system prompt and the newest message (the last one in req.history); if those two alone need more than the budget, return { error: "does_not_fit" }. Then walk the older messages from newest to oldest and keep each one while the total stays within the budget (total <= budget); stop at the first message that does not fit, and drop it and every older message. Never split a message. Return { sent, dropped, inputTokens }: sent = the system prompt id followed by the kept message ids in chronological order, dropped = the dropped ids in chronological order, inputTokens = the sum of the tokens sent. Before anything else, return { error: "invalid_input" } when contextLimit, reservedOutputTokens, system.tokens or any message''s tokens is not a whole number >= 0, when reservedOutputTokens >= contextLimit, or when history is empty or its last message does not have role "user". Token counts are precomputed per message. The test runner reads { requests } as JSON and prints the plan for each request.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
