INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_122'), 1, 'Which two messages are in every request no matter what, and how many tokens are left for everything else once you have also set aside the room for the answer?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_122'), 2, 'Look at the loop over the older messages: it should start just before the newest message and move towards index 0, and it should end for good the first time a message would push the total over the budget. Also look at how you build sent: the order you visit messages in is not the order you send them in.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_122'), 3, 'A similar task on a reading list: a learner has 50 minutes, the first video (12 min) is mandatory and so is the most recent one (15 min); the others, oldest to newest, are 10, 20, 5 and 8 min. Left: 50 - 12 - 15 = 23. Walking back from the most recent: 8 fits (15 left), 5 fits (10 left), 20 does not fit, so the walk stops and the 10-minute video is skipped too, even though it would fit. Watch order: 12, 5, 8, 15.');
