INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_122'), 'A short chat fits: everything is sent, nothing is dropped', '{"requests":[{"contextLimit":8192,"reservedOutputTokens":1000,"system":{"id":"sys","tokens":420},"history":[{"id":"m01","role":"user","tokens":180},{"id":"m02","role":"assistant","tokens":640},{"id":"m03","role":"user","tokens":95},{"id":"m04","role":"assistant","tokens":510},{"id":"m05","role":"user","tokens":140}]}]}', '[{"sent":["sys","m01","m02","m03","m04","m05"],"dropped":[],"inputTokens":1985}]', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_122'), 'The incident: a long tutoring chat keeps the system prompt and drops the oldest turns', '{"requests":[{"contextLimit":8192,"reservedOutputTokens":1000,"system":{"id":"sys","tokens":650},"history":[{"id":"m01","role":"user","tokens":310},{"id":"m02","role":"assistant","tokens":980},{"id":"m03","role":"user","tokens":260},{"id":"m04","role":"assistant","tokens":1240},{"id":"m05","role":"user","tokens":180},{"id":"m06","role":"assistant","tokens":870},{"id":"m07","role":"user","tokens":420},{"id":"m08","role":"assistant","tokens":1110},{"id":"m09","role":"user","tokens":150},{"id":"m10","role":"assistant","tokens":760},{"id":"m11","role":"user","tokens":330},{"id":"m12","role":"assistant","tokens":690},{"id":"m13","role":"user","tokens":210},{"id":"m14","role":"assistant","tokens":1340},{"id":"m15","role":"user","tokens":240}]}]}', '[{"sent":["sys","m05","m06","m07","m08","m09","m10","m11","m12","m13","m14","m15"],"dropped":["m01","m02","m03","m04"],"inputTokens":6950}]', 3, true, false, 2),
