-- challenge chal_quiz_aif_131 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_aif_131', (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aif-1-3' AND is_deleted = false LIMIT 1), 'temperature-repeatability-quiz', 'Temperature, repeatability and what to promise', 'Two pieces of evidence from the "Explain again" incident: five identical requests at temperature 0, and the recorded agreement of the explain-error prompt with two proposals for the fix.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_131');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_131');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_131'), 'The hint service logged five calls to a hosted API for the same error, one minute apart. Every request body had the same SHA-256 hash (same model, messages, temperature: 0, max_completion_tokens: 400):

run  body_sha256   output (first words)
1    9f3c...e21    "The variable `total` is declared as number, but..."
2    9f3c...e21    "The variable `total` is declared as number, but..."
3    9f3c...e21    "The variable `total` is declared as number, but..."
4    9f3c...e21    "The variable `total` has type number, but..."
5    9f3c...e21    "The variable `total` is declared as number, but..."

Statement: "Since temperature was 0 and the request bodies are identical, run 4 shows that the service must have sent a different prompt on that call."', 'single_choice'::question_type, 'False. The identical body hashes rule out a different prompt. Temperature 0 makes the model pick the most likely token, but on a hosted API that choice is the result of floating-point computations on shared, batched hardware, and when two tokens are almost equally likely a tiny numerical difference can flip the pick; after one different token the rest of the answer follows a different path. Provider documentation states that temperature 0 is not fully deterministic. The misconception is that temperature 0 is a determinism switch; it makes outputs much more repeatable, not identical.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_131') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_131'), 'Recorded runs of the explain-error prompt, compared after normalising spaces and case:

prompt          temperature  runs  agree with the most common answer
explain-ts2322  0            20    19 of 20
explain-ts2322  1            20    7 of 20

Requirement from the product owner: "When a learner clicks Explain again on the same error and code, they see the same explanation."

Proposal A: set temperature to 0 and call the model again on every click.
Proposal B: set temperature to 0, store the first answer under a key of model, prompt version, challenge, error text and code hash, and show the stored answer on later clicks.

Statement: "Proposal B meets the requirement more reliably than proposal A."', 'single_choice'::question_type, 'True. Proposal A still depends on the model repeating itself, and the recording shows that temperature 0 agreed in 19 of 20 runs, not 20 of 20, so about one click in twenty would still show a different text. Proposal B returns the stored text, which is identical by construction, and also saves the cost of the extra call; temperature 0 remains useful for the first answer of a factual feature. The key must contain everything that defines the question, so a change of code or prompt version produces a new answer. The misconception is that a sampling setting can guarantee the same output; only storing the answer can.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_131') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_aif_132 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aif_132', (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aif-1-3' AND is_deleted = false LIMIT 1), 'measure-answer-stability', 'Measure how repeatable an answer is', 'Learners reported CodeDev''s "Explain my error" bot as broken because "Explain again" gave a different answer each time. QA recorded several runs of the same prompts at different temperatures (a fixture: no model is called). Write measureStability(runs, threshold). A run is valid when prompt is a non-empty string, temperature is a finite number and output is a string; ignore every other run (failed requests have output null) and count them in ignored. Normalise each output before comparing: trim it, replace every run of whitespace with one space, and lower-case it. Group valid runs by prompt and temperature together. For each group return { prompt, temperature, runs, distinct, agreement, flagged }: runs = valid runs in the group, distinct = number of different normalised outputs, agreement = (count of the most common normalised output) / runs rounded to 2 decimals with Math.round(share * 100) / 100, flagged = true when the unrounded share is below threshold (a share equal to the threshold is not flagged). Return { results, ignored } with results sorted by prompt (compared with < and >), then by temperature from low to high. The test runner reads { threshold, runs } as JSON and prints the report.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_132');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_132'), 1, 'Two runs count as the same answer when exactly what is equal? Decide that first, then ask what you need to remember for each prompt and temperature pair to compute both the number of different answers and the size of the largest group of equal answers.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_132'), 2, 'Look at three places: the function that normalises a string (trim, a regular expression for whitespace, case), the key you group by (it must contain both the prompt and the temperature), and the comparison with threshold (use the share before rounding, and a strict "below").'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_132'), 3, 'A similar task on quiz votes: votes = ["B", "b ", "C", "B", "a"] for one question. Normalised: b, b, c, b, a. Counts: b 3, c 1, a 1, so 3 different answers and the most common one has 3 of 5 votes: share 0.6. With a threshold of 0.6 it is not flagged; with 0.61 it is. A Map from normalised text to count gives both numbers: its size and its largest value.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_132'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
