INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_132'), 'The incident: explain-ts2322 at temperature 0 and 1, ten recorded runs each', '{"threshold":0.8,"runs":[{"prompt":"explain-ts2322","temperature":0,"output":"The variable `total` is declared as number, but `input.value` is a string. Convert it with Number(input.value) before adding it."},{"prompt":"explain-ts2322","temperature":1,"output":"TypeScript error 2322: you assign a string to `total`, which is a number. Parse the input first, for example with Number()."},{"prompt":"explain-ts2322","temperature":0,"output":"The variable `total` is declared as number,  but `input.value` is a string.\nConvert it with Number(input.value) before adding it."},{"prompt":"explain-ts2322","temperature":1,"output":"The variable `total` is declared as number, but `input.value` is a string. Convert it with Number(input.value) before adding it."},{"prompt":"explain-ts2322","temperature":0,"output":"The variable `total` is declared as number, but `input.value` is a string. Convert it with Number(input.value) before adding it."},{"prompt":"explain-ts2322","temperature":1,"output":"`input.value` is always a string in the DOM. Use input.valueAsNumber or Number(input.value) so the types match."},{"prompt":"explain-ts2322","temperature":0,"output":"the variable `total` is declared as number, but `input.value` is a string. Convert it with Number(input.value) before adding it.\n"},{"prompt":"explain-ts2322","temperature":1,"output":"The variable `total` is declared as number,  but `input.value` is a string.\nConvert it with Number(input.value) before adding it."},{"prompt":"explain-ts2322","temperature":0,"output":"The variable `total` is declared as number, but `input.value` is a string. Convert it with Number(input.value) before adding it."},{"prompt":"explain-ts2322","temperature":1,"output":"The variable `total` has type number, but `input.value` is a string. Convert it with Number(input.value) before add