WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-aif-2-1' AND is_deleted = false);

-- challenge chal_quiz_aif_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_aif_211', (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aif-2-1' AND is_deleted = false LIMIT 1), 'llm-cost-from-tokens-quiz', 'Where does the LLM bill come from?', 'Two pieces of usage evidence from CodeDev''s AI features: one day of the "Ask about this lesson" bill, and the token counts of one conversation with the chat tutor.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_211');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_211');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_211'), 'Usage export for "Ask about this lesson", which sends the full text of the lesson with every question. One day, model chat-mini, example prices per 1M tokens: input $0.15, output $0.60.

date        model      requests  input_tokens  output_tokens  cost_usd
2026-09-14  chat-mini     8,000    96,000,000      1,200,000     15.12

Statement: "Output tokens cost four times as much as input tokens, so most of this feature''s bill is output, and shorter answers are the biggest saving available."', 'single_choice'::question_type, 'False. Price each column separately: input is 96,000,000 x $0.15 / 1,000,000 = $14.40 and output is 1,200,000 x $0.60 / 1,000,000 = $0.72, so 95% of the $15.12 is input. Each output token costs four times as much, but every request sends 12,000 input tokens (the whole lesson) and gets about 150 back, eighty times fewer. The biggest savings here are on the input side: send only the relevant part of the lesson (lesson 2), or let the repeated lesson text use the provider''s prompt cache. The misconception is that output always dominates; which side dominates depends on the feature, so compute both columns before you decide what to cut.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_211'), 'Usage logged by the "Ask the tutor" chat for one conversation. The learner''s four messages were 40, 35, 25 and 20 tokens long; the system prompt is 680 tokens.

turn  input_tokens  output_tokens
1     720           310
2     1,065         290
3     1,380         260
4     1,660         240

Statement: "Turn 4 is billed for more input tokens than turn 1 although the learner typed less, because each turn sends the system prompt and the whole conversation so far again."', 'single_choice'::question_type, 'True. The numbers add up exactly: turn 2 = 720 (turn 1''s input) + 310 (the tutor''s first answer) + 35 (the new message) = 1,065, and so on. A chat completion request is stateless: to continue a conversation the app sends the system prompt and every earlier message and answer again, and all of it is input. Input per turn therefore grows with the length of the conversation, not with the length of the new message. Even APIs that keep the conversation on the server for you generally still bill the earlier turns as input tokens, so check the provider''s pricing notes. The misconception is that the model "remembers" the chat and you pay only for the new message.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_aif_212 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aif_212', (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aif-2-1' AND is_deleted = false LIMIT 1), 'llm-cost-estimate', 'Estimate the cost of the hint bot from recorded requests', 'The hint bot''s first estimate priced only the prompt and was off by a factor of ten. Write the estimate the team should have made, from recorded usage instead of guesses. The input is a JSON object: prices maps a model name to { inputPer1M, outputPer1M, cachedInputPer1M? } in USD per 1 million tokens (example prices); requests is a list of { model, inputTokens, cachedInputTokens, outputTokens }, where cachedInputTokens are part of inputTokens; requestsPerDay and daysPerMonth drive the projection. requestCost(price, r) returns the unrounded USD cost: (uncached input tokens x inputPer1M + cachedInputTokens x cachedInputPer1M + outputTokens x outputPer1M) / 1,000,000, using inputPer1M for cached tokens when the model has no cached price. estimate(input) returns the report lines in this order: one line per request, numbered from 1 - "#<n> <model> <cost>" with toFixed(6), or "#<n> <model> error: unknown model" when the model is not in the price table, or "#<n> <model> error: invalid tokens" when a token count is not a whole number >= 0 or cachedInputTokens > inputTokens (check the model first); then "model <name> count=<n> cost=<sum>" for every model with at least one priced request, sorted by name; then "total count=<priced requests> errors=<error lines> cost=<sum>"; then "monthly requests=<requestsPerDay x daysPerMonth> cost=<average cost of a priced request x that number>". Sums add the unrounded costs and are printed with toFixed(6); the monthly cost uses toFixed(2) and is 0.00 when nothing was priced. A bad request becomes an error line and the report goes on. No real model is called: the requests are recorded usage.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_212');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_212'), 1, 'For one request, which groups of tokens appear on the bill, and which price applies to each group? Which group did the hint bot spreadsheet leave out?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_212'), 2, 'Look at how cachedInputTokens relates to inputTokens (it is a part of it, not an extra amount), at the optional cachedInputPer1M (the ?? operator gives a fallback), and at the order of the checks: price table first, then token counts. Keep running sums of the unrounded costs per model (a Map works) and overall, and call toFixed only when you build a line.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_212'), 3, 'A similar case with different numbers: model demo costs inputPer1M 1.00, cachedInputPer1M 0.50 and outputPer1M 4.00. A request with 2,000 input tokens, 1,000 of them cached, and 500 output tokens costs (1,000 x 1.00 + 1,000 x 0.50 + 500 x 4.00) / 1,000,000 = 3,500 / 1,000,000 = 0.0035, printed as 0.003500. If it is the only priced request and the app expects 10 requests a day for 30 days, the projection is 300 requests x 0.0035 = 1.05.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_212'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_212');
