-- challenge chal_quiz_aif_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_aif_221', (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aif-2-2' AND is_deleted = false LIMIT 1), 'llm-latency-quiz', 'What makes a hint slow?', 'Two measurements from CodeDev''s AI features: a short and a long chat request to the same model, and the hint bot before and after streaming was turned on.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_221');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_221');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_221'), 'Two calls of the "Ask the tutor" chat to the same model a minute apart. Call B is late in a long conversation, so it sends the whole history:

call  input_tokens  output_tokens  ttft_ms  total_ms
A              800            300      520     4,050
B            6,400            300    1,130     4,660

Statement: "The eight times longer input mainly delayed the first token; the time spent generating the 300-token answer stayed about the same."', 'single_choice'::question_type, 'True. Split each call into time to first token and generation time: A generated for 4,050 - 520 = 3,530 ms and B for 4,660 - 1,130 = 3,530 ms, so both wrote 300 tokens at about 85 tokens per second. The difference is all before the first token, where the model reads the input: 5,600 more input tokens cost about 0.6 s there. The total grew by 15%, not eightfold, because reading input is much faster per token than writing output. The misconception is that latency scales with the size of the whole request; input mostly moves time to first token, while output length drives the rest.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_221') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_221'), 'The team turned on streaming for hints and compared one day before and after (same model, same prompt v2):

                first text on screen  total_ms p50  total_ms p95  output_tokens avg  cost/day
not streaming   16,540 ms             16,540        26,820        1,350              $297.63
streaming          660 ms             16,600        26,900        1,350              $297.80

Statement: "Because the first words now appear after 660 ms instead of 16.5 s, streaming also cut the time until learners have the complete hint."', 'single_choice'::question_type, 'False. Streaming sends tokens to the screen as they are generated, so the first words appear after the time to first token instead of after the whole answer. The model still generates the same 1,350 tokens at the same speed: p50 and p95 total time are unchanged (within noise), and so is the cost, because the same tokens are billed. Streaming improves perceived speed, which matters a lot for a reader, but to make the complete hint arrive sooner you need fewer output tokens or a faster model. The misconception is that streaming makes the model faster or cheaper.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_221') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_aif_222 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aif_222', (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aif-2-2' AND is_deleted = false LIMIT 1), 'dashboard-wrong-price-unit', 'Spot the AI Mistake: wrong price unit', 'An AI assistant was asked to write the cost/latency dashboard script for the hint bot: "Input: recorded LLM calls of the hint bot (model, input tokens, output tokens, time to first token in ms, total time in ms) and the price table (USD per 1M tokens, separate input and output prices). For each model print the number of calls, p50 time to first token, p50 and p95 total time, output tokens per second and the total cost. Calls for a model missing from the price table must not crash the script." It was tried on a day of local-model calls, the latency columns matched the hand-computed values, and it went into the dashboard. On the first day with hosted models, finance asked why the dashboard says the hint bot costs about $96,700 a day when the provider''s usage page says about $298 for the same calls. The latency columns are still correct. Fix the script so that the cost of every model and the total match what the provider bills for the price table given (USD per 1M tokens, input and output priced separately). Keep the output format, the types and the test runner. The public tests pass on the assistant''s code; the hidden tests use hosted models with real (example) prices.', 'open', 'easy'::difficulty_question, 'fix_bug', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_222');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_222'), 1, 'The latency columns are right and the cost column is wrong by a large factor. Which numbers go into the cost of one call, and which price and which unit should each of them use?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_222'), 2, 'Look only at callCost and the constant just above it, and compare them with the request sent to the assistant: what unit does the price table use, and which price field does each token count use? Why did the local-model test not show the problem?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_222'), 3, 'A similar case with other numbers: a table in USD per 1M tokens with input 1.00 and output 4.00. A call with 2,000 input and 500 output tokens costs (2,000 x 1.00 + 500 x 4.00) / 1,000,000 = 0.004 USD. Dividing by 1,000 gives 4.0, a thousand times too much; pricing the 500 output tokens at 1.00 gives 0.0025, too little whenever output is the more expensive side. With prices of 0, as for a local model, every one of these versions prints 0.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_222'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
