-- challenge chal_quiz_aif_231 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_aif_231', (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aif-2-3' AND is_deleted = false LIMIT 1), 'choose-a-model-quiz', 'Which model fits this task?', 'Two model decisions on CodeDev: drafting support replies from tickets that contain learners'' personal data, and tagging forum posts with candidates compared on the team''s own eval set rather than a public leaderboard.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_231');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_231');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_231'), 'Task: draft a first reply to each support ticket for an agent to edit. Tickets contain learners'' names, email addresses and order IDs. Quality bar on the team''s eval set of 120 real tickets (personal data masked for the eval): 0.80. p95 budget: 10,000 ms.

model        runs on              approved processor  quality  p95_ms  cost per 1k requests (example prices)
fast-api     provider API         no                  0.88     2,400   $0.52
chat-mini    provider API         yes (DPA signed)    0.83     3,900   $0.95
local-27b    CodeDev GPU server   n/a (local)         0.81     8,800   $0.00

Statement: "fast-api is the right choice for this task, because it has the best quality and is the cheapest hosted model."', 'single_choice'::question_type, 'False. The tickets contain personal data, so the first question is where the data may go, not how good or cheap the model is. fast-api''s provider has no approved data processing agreement with CodeDev, so the real tickets may not be sent to it, whatever its score; the eval could use it only because the eval data was masked. That leaves chat-mini (an approved processor) and local-27b (the data never leaves CodeDev''s servers); both clear the 0.80 bar and the 10 s budget. local-27b''s $0 is only the per-token price: the GPU server, its power and its upkeep are real costs. The misconception is to rank models by quality and price first and treat data rules as a detail to check later; a data rule removes candidates before anything else is compared.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_231') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_231'), 'Forum post tagging: when a learner publishes a post, a model picks its topic tags. Posts are public and contain no personal data beyond the public display name. The team ran both candidates on 300 already-tagged posts. Budget: quality >= 0.85, p95 <= 5,000 ms.

model       public leaderboard rank  eval quality  p95_ms  cost per 1k requests (example prices)
chat-large  #2                       0.93          5,800   $3.40
chat-mini   #31                      0.87          1,400   $0.20

Statement: "For this feature chat-mini is the better choice: it clears the team''s own quality bar and latency budget at a seventeenth of the cost, and chat-large''s higher leaderboard rank does not change that."', 'single_choice'::question_type, 'True. The decision is made against this task''s constraints: chat-mini scores 0.87 on 300 real posts (bar 0.85), answers within 1.4 s at p95 (budget 5 s) and costs $0.20 against $3.40 per 1,000 requests. chat-large is better on the eval but misses the latency budget, and extra quality above the bar is only worth paying for if the bar itself is wrong - in which case raise the bar from evidence and run the eval again. A public leaderboard averages many tasks that are not yours, with prompts that are not yours. The misconception is that the best-ranked model is the best choice for every feature.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_231') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_aif_232 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aif_232', (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aif-2-3' AND is_deleted = false LIMIT 1), 'choose-a-model', 'Choose the cheapest model that fits the task', 'Every AI feature on CodeDev now needs a model decision in its design review, made from measured numbers instead of a favourite brand. Write chooseModel(input). The input is { task, models }. task has the typical request size (inputTokens, outputTokens) and the constraints maxCostPer1k (USD per 1,000 requests), maxP95Ms, minQuality (score on the team''s eval set, 0..1) and personalData (true when the prompts contain learners'' personal data). Each model has name, inputPer1M and outputPer1M (example USD prices per 1M tokens), p95Ms and quality (null when nobody has measured them for this task yet), contextTokens, local (runs on CodeDev''s own machines) and approvedProcessor (a hosted provider with an approved data processing agreement). costPer1k = (inputTokens x inputPer1M + outputTokens x outputPer1M) / 1000. Check each model in this order and describe each violation exactly: 1) personalData is true and the model is neither local nor approved -> "personal data would leave the company"; 2) contextTokens < inputTokens + outputTokens -> "context <contextTokens> < <needed> tokens needed"; 3) quality null -> "quality not measured", below minQuality -> "quality <quality> < <minQuality>"; 4) p95Ms null -> "p95 not measured", above maxP95Ms -> "p95 <p95Ms>ms > <maxP95Ms>ms"; 5) costPer1k above maxCostPer1k -> "cost per 1k <cost.toFixed(2)> > <maxCostPer1k>". A value equal to its limit fits; numbers print as template strings print them. If at least one model fits, return ["choose <name>", "reason: cheapest fitting model (<fitting> of <candidates> fit); cost per 1k <toFixed(2)>, p95 <p95Ms>ms, quality <quality>, data: <d>"] for the cheapest fitting model (equal cost: higher quality, then the smaller name in plain string order), where <d> is "no personal data" when personalData is false, otherwise "runs locally" or "approved processor". If none fits, return "no model fits" followed by "<name>: <violations joined with ", ">" for every candidate in input order; with no candidates at all, return ["no model fits", "(no candidates)"]. No model is called: the numbers come from recorded evals and timings.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_232');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_232'), 1, 'Which of the constraints can no amount of money fix, and what should happen to a candidate whose p95 or quality nobody has measured yet for this task?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_232'), 2, 'Write one function that returns the list of violations for one model, in the given order, and use it twice: an empty list means the model fits, and the same list is what you print when nothing fits. Watch null: in JavaScript null < 0.8 and null > 3000 are both false, so check for null before you compare. Sorting the fitting models with a comparator (cost, then quality, then name) gives the choice.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_232'), 3, 'A similar case with other numbers: a task with 1,000 input and 100 output tokens, maxCostPer1k 1, maxP95Ms 2000, minQuality 0.8 and personal data. Model X is hosted, not approved, inputPer1M 0.5, outputPer1M 2, p95 1500, quality 0.9: its cost per 1k is (500 + 200) / 1000 = 0.70, so its only violation is "personal data would leave the company". Model Y is local, p95 2000, quality 0.79: 2000 equals the limit and fits, so its only violation is "quality 0.79 < 0.8". Neither fits, so the answer is "no model fits" and one line per model.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_232'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
