DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_232');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_232'), 'Explain-error task without personal data: the cheapest model that fits', '{"task":{"name":"explain-error","inputTokens":1400,"outputTokens":250,"maxCostPer1k":2,"maxP95Ms":3000,"minQuality":0.8,"personalData":false},"models":[{"name":"chat-large","inputPer1M":2.5,"outputPer1M":10,"p95Ms":6200,"contextTokens":200000,"quality":0.91,"local":false,"approvedProcessor":true},{"name":"chat-mini","inputPer1M":0.15,"outputPer1M":0.6,"p95Ms":1900,"contextTokens":128000,"quality":0.84,"local":false,"approvedProcessor":true},{"name":"budget-api","inputPer1M":0.1,"outputPer1M":0.4,"p95Ms":1200,"contextTokens":64000,"quality":0.78,"local":false,"approvedProcessor":false},{"name":"open-hosted","inputPer1M":0.27,"outputPer1M":1.1,"p95Ms":2600,"contextTokens":64000,"quality":0.83,"local":false,"approvedProcessor":false},{"name":"local-8b","inputPer1M":0,"outputPer1M":0,"p95Ms":3800,"contextTokens":8192,"quality":0.79,"local":true,"approvedProcessor":false},{"name":"local-27b","inputPer1M":0,"outputPer1M":0,"p95Ms":5400,"contextTokens":32768,"quality":0.86,"local":true,"approvedProcessor":false}]}', '"choose chat-mini\nreason: cheapest fitting model (2 of 6 fit); cost per 1k 0.36, p95 1900ms, quality 0.84, data: no personal data"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_aif_232'), 'Autocomplete task that nothing fits: every violated constraint per candidate', '{"task":{"name":"live-autocomplete","inputTokens":600,"outputTokens":40,"maxCostPer1k":0.1,"maxP95Ms":800,"minQuality":0.8,"personalData":false},"models":[{"name":"chat-large","inputPer1M":2.5,"outputPer1M":10,"p95Ms":6200,"contextTokens":200000,"quality":0.91,"local":false,"approvedProcessor":true},{"name":"chat-mini","inputPer1M":0.15,"outputPer1M":0.6,"p95Ms":1900,"contextTokens":128000,"quality":0.84,"local":false,"approvedProcessor":true},{"name":"budget-api","inputPer1M":0.1,"outputPer1M":0.4,"p95Ms":1200,"contextTokens":64000,"quality":0.78,"local":false,"approvedProcessor":false},{"name":"open-hosted","inputPer1M":0.27,"outputPer1M":1.1,"p95Ms":2600,"contextTokens":64000,"quality":0.83,"local":false,"approvedProcessor":false},{"name":"local-8b","inputPer1M":0,"outputPer1M":0,"p95Ms":3800,"contextTokens":8192,"quality":0.79,"local":true,"approvedProcessor":false},{"name":"local-27b","inputPer1M":0,"outputPer1M":0,"p95Ms":5400,"contextTokens":32768,"quality":0.86,"local":true,"approvedProcessor":false}]}', '"no model fits\nchat-large: p95 6200ms > 800ms, cost per 1k 1.90 > 0.1\nchat-mini: p95 1900ms > 800ms, cost per 1k 0.11 > 0.1\nbudget-api: quality 0.78 < 0.8, p95 1200ms > 800ms\nopen-hosted: p95 2600ms > 800ms, cost per 1k 0.21 > 0.1\nlocal-8b: quality 0.79 < 0.8, p95 3800ms > 800ms\nlocal-27b: p95 5400ms > 800ms"', 3, true, false, 2),
