-- challenge chal_quiz_aif_311 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_aif_311', (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aif-3-1' AND is_deleted = false LIMIT 1), 'confident-wrong-answer-evidence', 'The Confident Wrong Answer: read the evidence', 'The CodeDev support bot told a learner to call submitLesson({ lessonId, force: true }), an option that never existed. Six statements on one evidence pack - the chat transcript (A), the prompt that was sent (B), the current docs (C) and the request log (D) - take you from reading the evidence to a hypothesis, past a wrong explanation, to the fix and its verification.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_311');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_311');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_311'), 'Evidence A - support widget, conversation sb_77f3:
21:14:02  learner u_5521  How do I submit my lesson when one hidden test still fails?
21:14:07  support bot     You can force the submission. Call submitLesson({ lessonId, force: true }) from your lab script: the force flag skips the hidden tests and marks the lesson as submitted. It has been supported since @codedev/lab 1.4.
21:31:40  learner u_5521  I tried it: CodeDevLabError: submitLesson: unknown option "force" (expected { lessonId, attemptId }). What now?

Evidence C - https://app.codedev.test/docs/lab/submit:
submitLesson({ lessonId, attemptId })                      @codedev/lab 2.x
  lessonId   string   the lesson to submit
  attemptId  string   the attempt created by `codedev test`
An attempt with a failing test is rejected (status "rejected", failedTests listed).
Tests cannot be skipped: fix the test, run `codedev test` again and submit the new attemptId.
CHANGELOG
2.0.0  2025-09-15  submitLesson(lessonId) is replaced by submitLesson({ lessonId, attemptId })
1.4.0  2024-11-02  codedev test prints the attempt id
1.0.0  2024-03-11  first release: submitLesson(lessonId)

Statement: "The force option does not exist in any version of @codedev/lab, so the bot did not repeat outdated documentation: it produced an option that was never documented."', 'single_choice'::question_type, 'True. The changelog in C lists every signature: 1.0 had submitLesson(lessonId), 2.0 has submitLesson({ lessonId, attemptId }), and 1.4 only changed what codedev test prints. No version has force, so this is not an outdated fact from before the model''s cutoff (that would have been the 1.x call submitLesson(lessonId)): it is a hallucination. Telling the two apart matters, because outdated knowledge points at the cutoff while an invented option shows the model filling a gap. The common mistake is to call every wrong answer "outdated training data".', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_311') AND order_index = 1)
    RETURNING id
)
