FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_311'), 'Evidence A - support widget, conversation sb_77f3:
21:14:02  learner u_5521  How do I submit my lesson when one hidden test still fails?
21:14:07  support bot     You can force the submission. Call submitLesson({ lessonId, force: true }) from your lab script: the force flag skips the hidden tests and marks the lesson as submitted. It has been supported since @codedev/lab 1.4.
21:31:40  learner u_5521  I tried it: CodeDevLabError: submitLesson: unknown option "force" (expected { lessonId, attemptId }). What now?

Statement: "Because the answer names an exact call, explains what the flag does and gives the version it appeared in, it was probably checked against the documentation and is more likely to be correct than a vaguer answer."', 'single_choice'::question_type, 'False. A model produces detail the same way it produces everything else: as likely next tokens. The precise call, the explanation and "since @codedev/lab 1.4" are all invented (C shows 1.4 changed something else). Nothing in the bot looked anything up: the prompt in B carried no documentation. The misconception is that confidence and detail signal verification; only a source the claim came from, such as a cited docs page, does.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_aif_311') AND order_index = 2)
    RETURNING id
)
