-- challenge chal_coding_aif_312 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_aif_312', (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'ai-llm-foundations') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-aif-3-1' AND is_deleted = false LIMIT 1), 'confident-wrong-answer-prompt-builder', 'The Confident Wrong Answer', 'The CodeDev support bot told a learner to call submitLesson({ lessonId, force: true }) - an option that never existed in @codedev/lab - and the request log shows docs_attached=0. The retrieval step finds the right documentation pages and passes them to buildPrompt(question, docs, options), most relevant first, but the bot still answers from what the model learned before its knowledge cutoff (January 2025) and never says it is unsure. Fix buildPrompt so that the prompt contains the first options.maxDocs documents in the given order (none when maxDocs is 0 or less), each as a line "[<id>] <title>" followed by a line with its text; tells the model to answer only from that documentation and to cite the [id] it used; tells it to reply "I''m not sure" when the documentation does not answer the question; and still contains the question. No real LLM is called: the file contains a fake model that replays recorded answers (do not change it or the test runner). Input: { docs: { id, title, text }[], options: { maxDocs }, questions: string[] }. Output: for each question a line "Q: <question>" and a line "A: <the fake model''s answer>".', 'open', 'easy'::difficulty_question, 'fix_bug', 20, true, false)
