function grade(results: { passed: boolean }[]): { score: number; passed: boolean } {
  const ok = results.filter((r) => r.passed).length;
  return { score: results.length ? Math.round((100 * ok) / results.length) : 0, passed: ok === results.length && ok > 0 };
}

async function onSubmit(sub: Submission) {
  const results = await runner.runHiddenTests(sub);
  const result = grade(results);
  const feedback = await aiTutor.review(sub.code, results);   // shown as "AI tutor feedback"
  await db.submissions.save({ id: sub.id, score: result.score, passed: result.passed, aiFeedback: feedback.text });
}

Statement: "In this pipeline the AI tutor''s review cannot change the learner''s score."', 'single_choice'::question_type, 'True. grade() takes only the hidden-test results, and the score is computed before the tutor is even called. The tutor''s output is stored in its own aiFeedback field and never passed to grade(); score and passed come from result alone. That is the design the lesson asks for: AI output is labelled feedback, the score comes from the tests. A proposal like "adjust the score by up to 10% for code quality" would have to change grade()''s signature, which makes it visible in review. The misconception is that a model which reviews the code must also have a say in the grade.', 2, 5
